"""Write exact-ten bounded review reports from inspected raw evidence and receipts."""
import csv, json
from pathlib import Path

B=Path(__file__).resolve().parent
ROOT=B.parent
QUEUE=list(csv.DictReader((B/'queue.csv').open(encoding='utf-8',newline='')))
CAT={r['sample_id']:r for r in csv.DictReader((ROOT/'shared-catalogues'/'TARGET-STATUS.csv').open(encoding='utf-8',newline=''))}

CASES={
'F031':dict(v='REFUTED',p='',e='',d='',finding='The S94 trough near BTJD 3875.09 and S104 trough near 4197.39 repeat in several other stars at identical epochs, with the same detailed asymmetric descent, intermediate recovery and gap-locked abrupt rise. S102 has a baseline step rather than a resolved eclipse. Those positive shared instrumental features refute the selected windows as evidence for this target eclipsing.',limits='This is a verdict on selected bulk flags, not a claim that the star cannot be binary. No secure same-kind raw eclipse centers or orbital period were measured.',next='Seek an isolated full eclipse in a sector with valid target-centered pixels before reconsidering the physical claim.'),
'F032':dict(v='PROBABLE',p='16.8905',e='2237.4566',d='4.7',finding='Sharp 4-6 ppt raw SAP eclipses at BTJD 2237.4566 (S34), 2980.6394 (S61), and 3706.9308 (S88) have matching narrow morphology. Their successive separations give 44 and 43 cycles at 16.890517 and 16.890499 d. Adjacent 43/42 and 45/44 cycle models miss the middle center by 0.198 and 0.190 d, larger than the 0.15-0.19 d event widths. P/2 through P/5 predict covered extra flat cores. The P=16.890508 d prediction at S99 BTJD 4061.631 lies in an actual 7.31-d data gap; the broad S99 detector window is a separate baseline structure.',limits='The photometric clock is a rounded blended-aperture recurrence, not an established orbit of the Gaia target. Fresh WCS pixels have valid target flux but a capable G13.015 neighbor only 0.36 pixel from the target; local drift moves the difference centroid off both positions. Source ownership is unresolved. Gaia SB1 P38.46865 d is incompatible with the observed 16.89-d clock; no source-specific conjunction tie is claimed. Local formal timing errors omit systematics, so no period error is supplied.',next='Obtain resolved target and neighbor photometry at another predicted sharp eclipse, then establish source ownership and orbital association.'),
'F033':dict(v='PLAUSIBLE',p='',e='',d='',finding='S28 shows a deep ingress immediately before a 2073.8117-2075.3881 BTJD gap and recovery after it; the eclipse center and full core are unobserved. The two S95 detector windows are broad baseline slopes and gap-adjacent steps with no matching deep eclipse morphology. A single partial event does not establish a repeat or clock.',limits='The partial S28 signal may be an eclipse, but its depth and center are not securely measured and source attribution is untested for that event. KSPSAP attenuation on the same photons does not by itself refute it.',next='Inspect valid source-centered pixels or another complete deep event and then test integer-cycle aliases.'),
'F034':dict(v='REFUTED',p='',e='',d='',finding='S94 shares the detailed BTJD~3875 trough, plateau, gap and abrupt recovery with four other stars. S65 and S95-S97 selected windows are broad ramps or baseline discontinuities beside gaps, not repeated resolved eclipse shapes despite many observed sectors.',limits='The selected flags have positive common or step context. This does not rule out other eclipses in the extensive cached coverage; no secure center or period is adopted.',next='Search for an isolated target-centered eclipse before reopening the selected-source claim.'),
'F035':dict(v='REFUTED',p='',e='',d='',finding='The selected S61 and S88 windows are dominated by baseline slopes and abrupt discontinuities; their local trapezoid fits hit bounds and do not reproduce repeated eclipse morphology. The nearly exact VSX EC|MISC source at 0.18 arcsec is a published EB alert, while ASAS-SN assigns ROT; the conflicting catalog classifications do not make these specific raw flags eclipses.',limits='This refutes the selected bulk detections only, not the published VSX classification or all possible variability of this source. Three cached sectors provide no measured secure eclipse clock.',next='Check the VSX light curve and obtain a complete resolved event at its listed 57.7-d clock before revising the physical status.'),
'F036':dict(v='REFUTED',p='',e='',d='',finding='S94 near 3875.08 and S104 near 4197.40 share detailed asymmetric trough and gap-locked recovery with other targets. The smaller S13 and S101 flags are low-amplitude/baseline-confounded and do not establish same-kind recurrence. The selected repeated-sector evidence is instrumental.',limits='No clean source-specific eclipse center, independent orbital clock or conjunction match was measured. An unrelated binary signal remains possible.',next='Find an isolated full raw event with valid WCS source attribution.'),
'F037':dict(v='REFUTED',p='',e='',d='',finding='S3, S4, S30 and S97 flagged dips lie on strong multi-day slopes and step/gap structures with inconsistent widths and shapes. Several nominal trapezoid depths are set by the local baseline rather than a discrete eclipse core. ASAS-SN reports generic VAR, not an EB identification.',limits='This is a bounded refutation of the selected windows as an eclipse sequence; it does not classify all of the star’s variability. S31 is available outside the cached set, but no provisional clean event clock makes it a decisive null.',next='Characterize the long-timescale variability and revisit only a discrete isolated event; include S31 if a clock emerges.'),
'F038':dict(v='PLAUSIBLE',p='',e='',d='',finding='Two broad, smooth ~10% raw SAP troughs occur in S13 near BTJD 1670.8 and S92 near 3806.5. They are distinct observing occasions and plausibly eclipses. The S13 event is observed through its trough despite an earlier data gap. Adjacent 51/52/53 same-kind cycle counts imply about 41.876/41.071/40.296 d and the 25-day sector spans do not resolve them. VSX EC ASAS J183903-3400.0 lies 0.11 arcsec from the target and is a strong known-EB identity alert; its listed P41.117241 d is an external prior, not a measured TESS cycle count. ASAS-SN ROT conflicts with VSX.',limits='Only two sparse broad events were measured; the width-bound local fits provide no precision timing error. The Gaia SB1 P41.0497 d resembles one conditional alias but does not prove it or source-specific conjunction geometry. The near-exact VSX identity is known prior evidence, not novelty.',next='Measure a third deep occasion or obtain historical light-curve timings with source-resolved pixels, then test adjacent integer cycles and Gaia conjunction.'),
'F039':dict(v='REFUTED',p='',e='',d='',finding='The S94 BTJD~3875 trough has the same detailed dip, partial recovery, gap and abrupt rise as four other stars. S104 near BTJD 4185.76 is a broad baseline step, not a resolved repeat of that waveform.',limits='The selected windows have positive instrumental/baseline context; this does not exclude an unrelated eclipse elsewhere. No measured same-kind clock is supported.',next='Require an isolated full target-centered eclipse before assigning a period.'),
'F040':dict(v='REFUTED',p='',e='',d='',finding='S94 near 3875.09 and S104 near 4197.29 reproduce the detailed asymmetric waveform and gap-locked recovery found in other stars. Their apparent repetition follows common instrumental structure, not a secure source-specific eclipse.',limits='No clean repeated eclipse or orbital association is established. Other variability of this target remains unclassified.',next='Inspect an isolated event with valid WCS target and neighbor photometry.'),
}

fields=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
results=[]
for row in QUEUE:
 sid=row['sample_id'];tic=row['tic'];c=CASES[sid];cat=CAT[sid]
 novelty='KNOWN' if sid in ('F035','F038') else 'SCOPED_NONMATCH'
 packet=json.loads((ROOT/'source-packets'/tic/'sources.json').read_text(encoding='utf-8'))
 meas=json.loads((B/tic/'lead-measurements.json').read_text(encoding='utf-8'))
 events=', '.join(f"S{x['sector']} {x.get('measured_center_btjd',x['screen_center_btjd']):.4f}" for x in meas['screen_flagged_dips'])
 path=(B/tic/'REPORT.md').resolve()
 lines=[f'# {sid} / TIC {tic}', '',f'**Physical verdict:** {c["v"]}; **bounded review:** COMPLETE; **catalogue status:** {novelty}.','',
        '## Raw observation and interpretation','',c['finding'],'',f'Detector windows and diagnostic local centers: {events}. These are not all accepted eclipse centers. Source: `lead-measurements.json` and `lead-event-panels.png`; alternative QLP check: `lead-alternative.json`. Raw QLP FITS SHA256 receipts are in `lead-measurements.json` and the sealed source packet.','',
        '## Timing, source and prior identity','',f'Gaia DR3 source {row["gaia_dr3"]}, selection SB1/SB2 period {row["gaia_period_days"]} d. Selection orbit is not itself an eclipse timing measurement. Shared catalogue: `{(ROOT/"shared-catalogues"/"TARGET-STATUS.csv").resolve()}`. {cat["novelty_status"]}.',
        '',f'Adopted measured photometric period: {c["p"]+" d" if c["p"] else "none"}. Reference measured center: {c["e"]+" BTJD" if c["e"] else "none"}. Representative raw depth: {c["d"]+" ppt" if c["d"] else "not robustly adopted"}.',
        '', '## Limits and next check','',c['limits'],'',c['next'],'',
        'This review is a bounded assessment of the selected bulk lead. Same-photon QLP reductions are processing checks, not another observing occasion. Gaia G-band neighbor flux is approximate. No exhaustive all-sector physical fit or publication claim is implied.','']
 if sid=='F032':lines+=['Numeric cycle and coverage receipts: `lead-alias-null.json`, `lead-alias-grid.json`, `lead-adjacent-cycle-check.json`; source attribution: `helper-pixels.json`.','']
 if sid=='F038':lines+=['VSX primary row: `../../shared-catalogues/vizier-raw/F038-vsx.tsv`; its near-exact positional match identifies a prior alert, while its period remains an external prior.','']
 path.write_text('\n'.join(lines),encoding='utf-8')
 results.append(dict(sample_id=sid,tic=tic,sample_stratum=row['sample_stratum'],physical_verdict=c['v'],full_review_completion='COMPLETE',novelty_status=novelty,period_days=c['p'],period_error_days='',primary_epoch_btjd=c['e'],depth_ppt=c['d'],limitations=c['limits'],next_check=c['next'],report=str(path)))
with (B/'RESULTS.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(results)
print([(x['sample_id'],x['physical_verdict'],x['novelty_status']) for x in results])
